// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("VotingStatus");

  // Voting Summary
  const [votingSummary, setVotingSummary] = useState({ totalVoted: 0, students: [] });

  // Reports
  const [reportElection, setReportElection] = useState(null);
  const [reportPosition, setReportPosition] = useState("");
  const [filteredResults, setFilteredResults] = useState({});

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => { try { const res = await api.get("/admin/voting-state"); setVotingOpen(res.data.votingOpen); } catch (err) { handleApiError(err); } };
  const fetchPendingUsers = async () => { try { const res = await api.get("/admin/pending-users"); setPendingUsers(res.data); } catch (err) { handleApiError(err); } };
  const fetchCandidates = async (electionId) => { 
    try { 
      const res = await api.get("/admin/candidates", { params: { electionId } }); 
      setCandidates(res.data); 
    } catch (err) { handleApiError(err); } 
  };
  const fetchLogs = async () => { try { const res = await api.get("/admin/logs"); setLogs(res.data); } catch (err) { handleApiError(err); } };
  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        setReportElection(firstElection.id);
        fetchResults(firstElection.id);
        fetchCandidates(firstElection.id);
      }
    } catch (err) { handleApiError(err); }
  };
  const fetchResults = async (electionId) => { try { const res = await api.get("/admin/results", { params: { electionId } }); setResults(res.data.positionResults || {}); setWinners(res.data.winners || {}); setFilteredResults(res.data.positionResults || {}); } catch (err) { handleApiError(err); } };
  const fetchVotingSummary = async () => { try { const res = await api.get("/admin/voting-summary"); setVotingSummary(res.data); } catch (err) { handleApiError(err); } };

  // ---------------- Actions ----------------
  const toggleVoting = async () => { try { const res = await api.post("/admin/toggle-voting"); setVotingOpen(res.data.votingOpen); setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`); } catch (err) { handleApiError(err); } };
  const approveUser = async (id) => { try { await api.post(`/admin/approve-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const rejectUser = async (id) => { try { await api.post(`/admin/reject-user/${id}`); fetchPendingUsers(); } catch (err) { handleApiError(err); } };
  const approveCandidate = async (id) => { try { await api.post(`/admin/approve-candidate/${id}`); fetchCandidates(selectedElection); } catch (err) { handleApiError(err); } };
  const deleteCandidate = async (id) => { if (!window.confirm("Delete this candidate?")) return; try { await api.delete(`/admin/candidates/${id}`); fetchCandidates(selectedElection); } catch (err) { handleApiError(err); } };
  const generateReport = async () => { try { const res = await api.post("/admin/generate-report"); setReportHash(res.data.hash); } catch (err) { handleApiError(err); } };

  const handleElectionChange = (id) => { 
    const election = elections.find((el) => el.id === id); 
    setSelectedElection(id); 
    setSelectedElectionVotingOpen(election?.votingOpen ?? false); 
    setReportElection(id); 
    fetchResults(id);
    fetchCandidates(id); // <-- fetch candidates for this election
  };

  const applyReportFilters = () => {
    let filtered = { ...results };
    if (reportPosition) filtered = { [reportPosition]: filtered[reportPosition] || [] };
    setFilteredResults(filtered);
  };
  const resetReportFilters = () => { setReportElection(selectedElection); setReportPosition(""); setFilteredResults(results); };
  const exportExcel = () => { console.log("Export Excel:", filteredResults); alert("Export Excel triggered"); };
  const exportPDF = () => { console.log("Export PDF:", filteredResults); alert("Export PDF triggered"); };
  const printReport = () => { window.print(); };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates(selectedElection);
      await fetchLogs();
      await fetchElections();
      await fetchVotingSummary();
    };
    init();
  }, [token]);

  // ---------------- Render ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "VotingStatus":
        return (
          <Card title="Voting Status">
            <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>{votingOpen ? "Open" : "Closed"}</p>
            <button onClick={toggleVoting} style={{ marginTop: "10px", padding: "10px 20px", borderRadius: "8px", border: "none", backgroundColor: votingOpen ? "#dc3545" : "#28a745", color: "#fff", cursor: "pointer", fontWeight: "bold" }}>{votingOpen ? "Close Voting" : "Open Voting"}</button>
          </Card>
        );
      case "VotingSummary":
        return (
          <Card title="Voting Summary">
            <h3>Total Students Voted: {votingSummary.totalVoted}</h3>
            <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "15px" }}>
              <thead>
                <tr style={{ background: "#f1f1f1" }}>
                  <th style={{ padding: "8px", textAlign: "left" }}>Student Number</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Status</th>
                </tr>
              </thead>
              <tbody>
                {votingSummary.students.length > 0 ? votingSummary.students.map((s, i) => (
                  <tr key={i} style={{ borderTop: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{s.studentNumber}</td>
                    <td style={{ padding: "8px" }}>{s.name}</td>
                    <td style={{ padding: "8px", fontWeight: "bold", color: "green" }}>{s.status}</td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan="3" style={{ padding: "10px", textAlign: "center", color: "#777" }}>No students have voted yet.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </Card>
        );
      case "PendingUsers":
        return (
          <Card title="Pending Voter Registrations">
            {pendingUsers.length === 0 ? <p style={{ color: "#777", fontStyle: "italic" }}>No pending users.</p> :
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Student #</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Email</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingUsers.map(u => (
                    <tr key={u.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{u.studentNumber}</td>
                      <td style={{ padding: "8px" }}>{u.name}</td>
                      <td style={{ padding: "8px" }}>{u.email}</td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        <button onClick={() => approveUser(u.id)} style={{ marginRight: "5px", background: "#28a745", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Approve</button>
                        <button onClick={() => rejectUser(u.id)} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Reject</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>}
          </Card>
        );
      case "Candidates":
        return (
          <Card title="Candidates">
            <div style={{ marginBottom: "15px" }}>
              <label htmlFor="electionSelect" style={{ marginRight: "10px", fontWeight: "bold" }}>Election Period:</label>
              <select id="electionSelect" value={selectedElection || ""} onChange={(e) => handleElectionChange(parseInt(e.target.value))}>
                {elections.map(el => (
                  <option key={el.id} value={el.id}>
                    {el.name} ({new Date(el.startsAt).toLocaleDateString()} - {new Date(el.endsAt).toLocaleDateString()})
                  </option>
                ))}
              </select>
            </div>
            {candidates.length === 0 ? (
              <p style={{ color: "#777", fontStyle: "italic" }}>No candidates registered for this election.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Position</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Forms</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Status</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map(c => (
                    <tr key={c.id} style={{ borderTop: "1px solid #eee", backgroundColor: c.approved ? "#e6ffe6" : (!c.documents || c.documents.length === 0) ? "#ffe6e6" : "#fff" }}>
                      <td style={{ padding: "8px" }}>{c.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                      <td style={{ padding: "8px" }}>
                        {c.documents && c.documents.length > 0 ? c.documents.map((doc, idx) => (
                          <div key={idx}>
                            <a href={`${process.env.REACT_APP_SERVER_URL || "http://localhost:4000"}/uploads/candidate-docs/${doc}`} target="_blank" rel="noopener noreferrer" style={{ color: "#007bff", textDecoration: "underline" }}>Form {idx + 1}</a>
                          </div>
                        )) : <span style={{ color: "#dc3545", fontStyle: "italic", fontWeight: "bold" }}>No form submitted</span>}
                      </td>
                      <td style={{ padding: "8px", textAlign: "center", fontWeight: "bold", color: c.approved ? "green" : "orange" }}>{c.approved ? "Approved" : "Pending"}</td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        <button onClick={() => approveCandidate(c.id)} disabled={c.approved || !c.documents || c.documents.length === 0} style={{ marginRight: "5px", background: c.approved || !c.documents || c.documents.length === 0 ? "#6c757d" : "#28a745", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: c.approved || !c.documents || c.documents.length === 0 ? "not-allowed" : "pointer" }}>{c.approved ? "Approved" : !c.documents || c.documents.length === 0 ? "No Form" : "Approve"}</button>
                        <button onClick={async () => {
                          const comment = prompt("Enter rejection reason for candidate:");
                          if (comment !== null) {
                            await deleteCandidate(c.id);
                            alert("Candidate rejected: " + comment);
                          }
                        }} style={{ background: "#dc3545", color: "#fff", border: "none", borderRadius: "6px", padding: "5px 10px", cursor: "pointer" }}>Reject</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );
      case "Reports":
        return (
          <Card title="Reports">
            <div style={{ marginBottom: "15px", display: "flex", gap: "10px" }}>
              <label>Election:</label>
              <select value={reportElection || ""} onChange={(e) => setReportElection(parseInt(e.target.value))}>
                {elections.map(el => (
                  <option key={el.id} value={el.id}>{el.name}</option>
                ))}
              </select>
              <label>Position:</label>
              <input type="text" value={reportPosition} onChange={(e) => setReportPosition(e.target.value)} placeholder="Filter by position" />
              <button onClick={applyReportFilters}>Apply</button>
              <button onClick={resetReportFilters}>Reset</button>
            </div>
            <div style={{ marginBottom: "10px", display: "flex", gap: "10px" }}>
              <button onClick={exportExcel}>Export Excel</button>
              <button onClick={exportPDF}>Export PDF</button>
              <button onClick={printReport}>Print</button>
            </div>
            <div>
              {Object.keys(filteredResults).length === 0 ? <p>No results available</p> : Object.entries(filteredResults).map(([position, candidates]) => (
                <div key={position} style={{ marginBottom: "10px" }}>
                  <h4>{position}</h4>
                  <ul>
                    {candidates.map((c, idx) => <li key={idx}>{c.name} - Votes: {c.votes}</li>)}
                  </ul>
                </div>
              ))}
            </div>
          </Card>
        );
      default:
        return null;
    }
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "Arial, sans-serif" }}>
      {/* Sidebar */}
      <div style={{ width: sidebarOpen ? "220px" : "60px", background: "#343a40", color: "#fff", paddingTop: "20px", transition: "width 0.3s", display: "flex", flexDirection: "column" }}>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: "none", border: "none", color: "#fff", fontSize: "20px", marginBottom: "20px", cursor: "pointer" }}>{sidebarOpen ? "⏪" : "⏩"}</button>
        <nav style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {["VotingStatus","VotingSummary","PendingUsers","Candidates","Reports"].map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab===tab ? "#007bff" : "transparent", border: "none", color: "#fff", padding: "10px 15px", textAlign: "left", cursor: "pointer", borderRadius: "6px" }}>{tab}</button>
          ))}
        </nav>
      </div>
      {/* Main Content */}
      <div style={{ flex: 1, padding: "20px", backgroundColor: "#f4f6f8" }}>
        {message && <div style={{ marginBottom: "15px", color: "red", fontWeight: "bold" }}>{message}</div>}
        {renderContent()}
      </div>
    </div>
  );
}
